#include <iostream>
#include <fstream>
using namespace std;

bool zawieraCyfre(int n, int c) {
    while (n > 0) {
        if (n % 10 == c) return true;
        n /= 10;
    }
    return false;
}

int main() {
    ifstream plik("liczby.txt");
    int n;
    int ile = 0, suma = 0;
    while (plik >> n) {
        if (zawieraCyfre(n, 7)) {
            ile++;
            suma += n;
        }
    }
    cout << "Liczby zawierajace cyfre 7: " << ile << endl;
    cout << "Suma tych liczb: " << suma << endl;
    return 0;
}
```

